      const label = a.rawName ? bound(a.rawName, 40).replace(/'/gu, '’') : '';
      if (!label && (a.role === 'group' || a.role === 'row' || a.role === 'listitem' || a.role === 'article' || a.role === 'region')) {
        if (a.role === 'group' || a.role === 'region') continue;
      }
      const ordinal = ordinals.get(a.i);
