// Pure offline gates G1 / G2 over a recorded S3 outline. No harness code is modified; nothing here talks to a model.
const QUOTED = '"(?:[^"\\\\]|\\\\.)*"';

const LINE = new RegExp(`^(\\s*)- (\\S+)(?: (${QUOTED}))?(?: \\[(e\\d+)\\])?(.*)$`, 'u');

const MORE_OPTIONS = /^(\s*)… (\d+) more options\s*$/u;

