    if (m) { nodes.push({ idx, kind: 'moreOptions', depth: m[1].length / 2, count: Number(m[2]) }); return; }
    m = MORE_NODES.exec(raw);
    if (m) { moreNodes = Number(m[1]); nodes.push({ idx, kind: 'moreNodes', depth: -1, count: moreNodes }); return; }
